          catch ($e) {
              my $res = BS::Ext::pacman->pkg_query( $dep_pkgargs{name} );
  
              BS::Common::dmsg $res;
              chomp $res->out->[-1];
  
              try {
                  $dep_pkgargs{base} //= BS::Ext::pacinfo->pkgbase(
                      $res->out->[-1],
                      resolve_deps => 0,
                      no_dupes     => 1
                  );
  
                  $dep_pkgargs{base} = $dep_pkgargs{base}->out
                    if $dep_pkgargs{base};
              }
              catch ($e) {
                  croak np $e
              }
          }
      }
  
      if ( $args{fetch} ) {
          $class->fetch( $dep_pkgargs{base}, %args );
      }
  
      \%dep_pkgargs;
  }
  
