      return undef unless $key && $val;
  
      const my $DEPKEY_ANY_RE => qr/depends/i;
  
      if ( $key =~ $DEPKEY_ANY_RE ) {
          $val = $class->parse_dep( $val, %args );
      }
  
      return $key, $val;
  }
