use utf8;
use v5.40;

use lib 'lib';

#use BS::Common;
use Data::Dumper;
use IPC::Run3;

if ( $ENV{DEBUG} ) {
    warn Dumper( { argv => \@ARGV } ) . "\n";
}

my @out;
my @overwrite = $ARGV[0] eq '-S' ? qw(--overwrite '*' --noconfirm) : ();
push @overwrite, '--needed' if $ENV{ASNEEDED};

my $ret = run3(
    [ 'pacman', @overwrite, '--verbose', @ARGV ],
    \*STDIN,
    sub { chomp $_[0]; say $_[0]; push @out, $_[0] },
    sub { chomp $_[0]; warn $_[0]; }
);

my $status = $?;

if ( $ENV{DEBUG} ) {
    warn Dumper(
        overwrite => \@overwrite,
        status    => $status,
        ret       => $ret,
        out       => \@out
       ) . "\n"
}

exit $status
